#include "bench_safety.h"
#include <ArduinoJson.h>
void BenchSafety::begin(){pinMode(jumperPin_,INPUT_PULLUP);}void BenchSafety::sendMotor(uint8_t motor,uint16_t pwm){uint8_t payload[16]={};for(int i=0;i<8;i++){uint16_t value=(i==motor)?pwm:1000;payload[2*i]=value&0xff;payload[2*i+1]=value>>8;}msp_.request(MspCommand::SET_MOTOR,payload,16);}void BenchSafety::sendMinimum(){sendMotor(255,1000);active_=false;}
void BenchSafety::update(WiFiUDP&udp,uint32_t nowMs){if(active_&&nowMs-lastCommandMs_>WATCHDOG_MS&&!msp_.busy())sendMinimum();int bytes=udp.parsePacket();if(!bytes)return;char input[256];int n=udp.read(input,255);if(n<=0)return;input[n]=0;StaticJsonDocument<256>d;if(deserializeJson(d,input))return;if(!compiledEnabled_||digitalRead(jumperPin_)!=LOW||String((const char*)d["type"])!="bench_motor"||String((const char*)d["phrase"])!="PROPS_REMOVED")return;uint32_t sequence=d["sequence"]|0;if(sequence<=lastSequence_)return;int motor=d["motor"]|-1,pwm=d["pwm"]|0;if(motor<0||motor>3||pwm<1000||pwm>1100||msp_.busy())return;/* TODO: require FC disarmed after Matrix MSP_STATUS semantics are verified. */lastSequence_=sequence;lastCommandMs_=nowMs;active_=true;sendMotor((uint8_t)motor,(uint16_t)pwm);}
